@Component("clinician-handler")
@ProcessingGroup("clinician-processing-group")
public class ClinicianEventHandler {
	
	// core constructor
	ClinicianEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateClinicianEvent
     */
    @EventHandler
    public void handle( CreateClinicianEvent event) {
        entityManager.persist(new Clinician(event.getClinicianId(), event.getFirstName(), event.getLastName(), event.getLicenseNumber(), event.getCareTeams(), event.getAppointments(), event.getEncounters(), event.getProcedures(), event.getImagingReports(), event.getClinicianType(), event.getSpecialty()));
    }

    /*
     * @param	event UpdateClinicianEvent
     */
    @EventHandler
    public Clinician handle( UpdateClinicianEvent event) {
    	entityManager.merge(new Clinician(event.getClinicianId(), event.getFirstName(), event.getLastName(), event.getLicenseNumber(), event.getCareTeams(), event.getAppointments(), event.getEncounters(), event.getProcedures(), event.getImagingReports(), event.getClinicianType(), event.getSpecialty()));
    }
    
    /*
     * @param	event DeleteClinicianEvent
     */
    @EventHandler
    public void on( DeleteClinicianEvent event) {
    	Clinician entity = new Clinician();
   
    	// ------------------------------------------
    	// apply the ClinicianId
    	// ------------------------------------------
    	entity.setClinicianId( event.getClinicianId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ClinicianRepository clinicianEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ClinicianEventHandler.class.getName());

}
